  "prediction_basis_card_ids": ["C07", "C01", "C18", "C15", "C16", "C23", "C13", "C05"],
  "claims": [
    {
      "claim": "The closest structural comparator nilotinib has a human fasted absolute oral bioavailability of about 31%, above the 20% threshold; its low bioavailability is attributed to fasted-state precipitation rather than intrinsically poor absorption.",
      "card_ids": ["C07", "C26", "C40"]
    },
    {
      "claim": "Human absolute or extent-of-bioavailability records for structurally related basic-amine, sulfonyl, and heteroaromatic drugs are all at or above 20%: bitopertin high, PNU-96391 60%, bidisomide 42.6-62%, brexpiprazole 95%, daridorexant 62%, risperidone 70%, mofarotene high, and compound 12 67%.",
      "card_ids": ["C05", "C23", "C13", "C42", "C18", "C15", "C16", "C09", "C01"]
    },
    {
      "claim": "L3 oral exposure records for related kinase inhibitors show substantial systemic exposure after oral dosing in humans (imatinib AUC 40.1 µg·h/mL at 400 mg; erlotinib Cmax 1.83-2.64 µg/mL; dasatinib AUC 10 µg·h/mL at 200 mg), consistent with F >= 20% but not directly quantifying bioavailability.",
      "card_ids": ["C46", "C52", "C47", "C54"]
    },
    {
      "claim": "L4 solubility and dissolution records are for other molecules and formulations (imatinib, dasatinib, erlotinib, talinolol, raloxifene, and compounds 16/31) and do not provide query-specific permeability or absorption data; they neither establish F < 20% nor override the human F records.",
      "card_ids": ["C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64", "C65", "C66"]
    },
    {
      "claim": "L5 efflux records show that P-gp and BCRP can restrict intestinal absorption of related kinase inhibitors (dasatinib oral AUC increased in Abcb1-deficient mice; tandutinib efflux in Caco-2 cells), but these are mechanistic observations for other molecules and do not quantify query F or establish F < 20%.",
      "card_ids": ["C69", "C70", "C78"]
    },
    {
      "claim": "Low F values in rat or micro-suspension studies (daridorexant 9%, bitopertin 14-23%, bidisomide 20-25%) are species- and formulation-specific and do not overturn the corresponding human gold records.",
      "card_ids": ["C39", "C34", "C30", "C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77", "C78"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability, AUC, or Cmax data for the query molecule.",
    "No query-specific intestinal permeability, solubility, or efflux experiment; L4 and L5 records are for other molecules.",
    "No formulation or prandial condition is specified for the query; nilotinib's fasted precipitation issue may not apply.",
    "Closest comparator nilotinib F = 31% fasted is close to the 20% threshold; the margin is modest.",
    "Low F values from rat or micro-suspension studies may not translate to human oral exposure for this chemotype."
  ],
  "decision_summary": "Predicted high: F >= 20% remains better supported because the closest nilotinib-like comparator has human fasted F about 31% and all transferable human absolute or extent F records for related basic-amine sulfonyl heteroaromatic drugs are at or above 20%. L5 efflux records are mechanistic and for other molecules; they do not establish F < 20%. Confidence remains moderate due to indirect evidence and threshold proximity."
}

